/* global Office, console */

// v1.0.6: 公式の正準パターンに戻す。
//   - Office.actions.associate を「トップレベルで無条件に」呼ぶ
//     (Office.onReady でラップしない / 楽観的チェーン ?. で握りつぶさない)
//   - 新しい Outlook (browser runtime) でも Classic (JS-only runtime) でも動く唯一の安全形
//   - 計装(console.log)を仕込み、olk.exe --devtools で「実行されたか」を可視化する
//
// このビルドは診断用。ハンドラは常に errorMessage を出して送信をブロックする
// (= このダイアログが出れば「関連付け成功」の確証。確認後 v1.0.7 で本来のチェックに戻す)
const BUILD_TAG = "v1.0.6-toplevel-associate-2026-06-09";

console.log(`[PauseMan] module eval start ${BUILD_TAG}`);

function onMessageSendHandler(event: Office.AddinCommands.Event) {
  console.log(`[PauseMan] handler ENTERED ${BUILD_TAG}`);
  event.completed({
    allowEvent: false,
    errorMessage:
      `${BUILD_TAG}\n\n` +
      `✅ ハンドラが実行されました (${new Date().toISOString()})。\n` +
      `このダイアログが見えれば「関連付け」は成功です。\n` +
      `次は本来の誤送信チェックに戻します。`,
  } as any);
  console.log(`[PauseMan] event.completed called ${BUILD_TAG}`);
}

// === 正準パターン: トップレベルで無条件に登録 ===
// commands.html は office.js を(defer なしの)ブロッキングで先に読み込むので、
// この行が走る時点で Office.actions は必ず存在する。ガードは付けない。
Office.actions.associate("onMessageSendHandler", onMessageSendHandler);

console.log(`[PauseMan] associate() called at top level ${BUILD_TAG}`);
